import { writeFileSync } from "node:fs";
import { pathToFileURL } from "node:url";
import "../economy-audit/source-loader.mjs";
import { collectAuthoredMetadata, inventoryRelease } from "./bank.mjs";

const cell = s => String(s ?? "unknown").replaceAll("|", "\\|").replaceAll("\n", " ");
export function renderInventory(report) {
  const t=report.totals;
  const lines=["# Live question inventory — 2026-10-28", "", "Generated by `npm run clinical:lint -- --inventory docs/research/question-inventory-20261028.md`. Advisory lexical findings require editorial and clinical review; a warning is neither proof of a flaw nor a difficulty estimate.", "",
    "**PIPELINE STATUS:** independent review two passed 17 exact versions, retained unchanged. The 56 returned versions now have v6 drafts: 35 explicitly basic and 21 application items, awaiting independent re-review and manager acceptance. Pipeline-qualified drafts may enter invited beta under the existing unapproved label; this worker publishes nothing. Exact owner-approved pilot versions have existing clinical review metadata; approval never transfers to another identity.", "",
    "Melissa Rowland (clinical sign-off) approved eleven exact pilot versions: eight on 2026-10-29 and A11/A30/A40 on 2026-11-02. Current round-three/batch-one packets contain 43 main tasks and 30 context revisions, all needs_clinician_review. See question-round3-20261102.json and question-batch1-20261102.json; their before fields are the exact v5 drafts from independent review two; pipelinePassed records editorial PASS separately from clinical approval.", "",
    "Scope: "+report.scope, "", "Release: `"+report.releaseId+"`; linter: `"+report.linterVersion+"`.", "",
    "| Measure | Total |", "|---|---:|", ...Object.entries(t).filter(([,v])=>typeof v==="number").map(([k,v])=>"| "+k+" | "+v+" |"), "",
    "Facility entry indices 0–4 are displayed separately from educational tier. Neither is a measured resident difficulty. Option-count totals count distinct variant IDs; a reused ID with multiple counts would appear in each count.", "",
    "| Facility entry index | Variants |", "|---|---:|", ...Object.entries(t.byPriorityStage).map(([k,v])=>`| ${k} | ${v} |`), "",
    "| Options | Variants |", "|---|---:|", ...Object.entries(t.byOptionCount).map(([k,v])=>`| ${k} | ${v} |`), "",
    "| Advisory rule | Variants flagged |", "|---|---:|", ...Object.entries(t.variantsByRule).map(([k,v])=>`| ${k} | ${v} |`), "",
    "## Rewrite order and exposure limitation", "", report.exposureBasis, "",
    "1. Review the explicit tutorial sequence separately; keep deliberate interface onboarding easy and labelled. Review other tier-0 recognition/terminology items as foundational candidates, rather than forcing ambiguity to meet resident targets.",
    "2. Within each facility entry index, start with variants referenced by more cases, then findings needing review. This is a structural priority proxy, with voluntary tester flags and owner review as qualitative inputs. No per-question correctness collection or analytics is used.",
    "3. Proceed through entry indices 0, 1, 2, 3, 4. Review adjacent variants of the same concept together for surface-cue memorisation and preserve concept identity unless clinical meaning changes.",
    "4. The pilot revisions are labelled with intended cognitive scope. All other difficulty intent is unclassified until a clinician/editor reviews it; tutorialEligible alone does not establish an intentionally easy item.", "",
    "## Complete census", "", "One row per live variant identity. References count cases, not plays. A version of `unmapped` identifies missing exported authoring metadata. Legacy approval receipts supply declared version/status for some IDs; this census does not revalidate their byte-level approval. Unknown educational tiers remain unknown rather than being inferred from facility level. Use the JSON report for full occurrence spans, metadata origins and profile identities.", "",
    "| Variant ID | Concept | Entry index / tier | Options | Cases / nodes | Intent | Version / review | Lint findings: exact field and phrase |", "|---|---|---|---:|---|---|---|---|"];
  for(const v of report.variants){
    const flags=v.findings.map(f=>f.rule+": "+f.evidence.map(e=>e.field+(e.choiceId?"["+e.choiceId+"]":"")+" = “"+e.text+"”").join("; ")).join("<br>")||"none";
    const intent=v.tutorialSequence?"tutorial sequence":v.educationalIntent+(v.educationalTier===0?"; foundational candidate":"")+(v.tutorialEligible?"; tutorial eligible":"");
    lines.push("| "+[v.questionVariantId,v.conceptId,v.facilityStages.join(",")+" / "+(v.educationalTier??"unknown"),v.optionCounts.join(","),v.caseReferenceCount+" / "+v.nodeOccurrences,intent,(v.authoredVersions.join(", ")||"unmapped")+" / "+(v.reviewStatuses.join(", ")||"unmapped")+(v.metadataOrigins.includes("approval_record")?" (approval record only)":""),flags].map(cell).join(" | ")+" |");
  }
  return lines.join("\n")+"\n";
}
export async function assembleReport() {
  const content=await import("../../packages/clinical-content/src/index.ts");
  return inventoryRelease(content.SYNTHETIC_CLINICAL_RELEASE,collectAuthoredMetadata(content),{
    tutorialCaseIds:[content.FIRST_TUTORIAL_CASE_ID,content.SECOND_TUTORIAL_CASE_ID],
    pilotRevisions:content.QUESTION_QUALITY_CURRENT_REVISIONS??[],
  });
}
export async function main(args=process.argv.slice(2)) {
  const options={};
  for(let i=0;i<args.length;i++){
    const a=args[i];
    if(a==="--summary")options.summary=true;
    else if(["--json","--inventory"].includes(a)){
      if(!args[i+1]||args[i+1].startsWith("--"))throw new Error("Missing value for "+a);
      options[a.slice(2)]=args[++i];
    }else throw new Error("Unknown argument: "+a);
  }
  const report=await assembleReport();
  if(options.inventory)writeFileSync(options.inventory,renderInventory(report));
  if(options.json)writeFileSync(options.json,JSON.stringify(report,null,2)+"\n");
  if(options.summary||options.inventory||options.json)process.stdout.write(JSON.stringify({releaseId:report.releaseId,linterVersion:report.linterVersion,totals:report.totals},null,2)+"\n");
  else process.stdout.write(JSON.stringify(report,null,2)+"\n");
}
if(process.argv[1]&&import.meta.url===pathToFileURL(process.argv[1]).href)main().catch(e=>{process.stderr.write(e.message+"\n");process.exitCode=1;});

